class Solution {
    public int minCostClimbingStairs(int[] cost) {
        int n = cost.length;
        int[] dp = new int[n + 1];
        dp[0] = 0;
        dp[1] = 0;
        for (int step = 2; step <= n; step++) {
            int fromOneBelow = dp[step - 1] + cost[step - 1];
            int fromTwoBelow = dp[step - 2] + cost[step - 2];
            dp[step] = Math.min(fromOneBelow, fromTwoBelow);
        }
        return dp[n];
    }
}

class Solution {
    public int minCostClimbingStairs(int[] cost) {
        int twoStepsBack = 0;
        int oneStepBack = 0;
        for (int step = 2; step <= cost.length; step++) {
            int current = Math.min(oneStepBack + cost[step - 1], twoStepsBack + cost[step - 2]);
            twoStepsBack = oneStepBack;
            oneStepBack = current;
        }
        return oneStepBack;
    }
}

import java.util.Arrays;

class Solution {
    public int minCostClimbingStairs(int[] cost) {
        int[] memo = new int[cost.length + 1];
        Arrays.fill(memo, -1);
        return minCost(cost, cost.length, memo);
    }

    private int minCost(int[] cost, int step, int[] memo) {
        if (step <= 1) {
            return 0;
        }
        if (memo[step] != -1) {
            return memo[step];
        }
        int fromOneBelow = minCost(cost, step - 1, memo) + cost[step - 1];
        int fromTwoBelow = minCost(cost, step - 2, memo) + cost[step - 2];
        memo[step] = Math.min(fromOneBelow, fromTwoBelow);
        return memo[step];
    }
}

class Solution {
    public int minCostClimbingStairs(int[] cost) {
        int n = cost.length;
        for (int i = 2; i < n; i++) {
            cost[i] += Math.min(cost[i - 1], cost[i - 2]);
        }
        return Math.min(cost[n - 1], cost[n - 2]);
    }
}

import java.util.Arrays;

class Solution {
    public int minCostClimbingStairs(int[] cost) {
        int n = cost.length;
        int[] dist = new int[n + 1];
        Arrays.fill(dist, Integer.MAX_VALUE / 4);
        dist[0] = cost[0];
        dist[1] = cost[1];

        for (int step = 0; step < n; step++) {
            for (int jump = 1; jump <= 2; jump++) {
                int next = step + jump;
                if (next > n) {
                    continue;
                }
                int nextCost = next == n ? 0 : cost[next];
                dist[next] = Math.min(dist[next], dist[step] + nextCost);
            }
        }

        return dist[n];
    }
}
